import { Link, useSearchParams } from 'react-router-dom';

import ClubsList from '@apps/Clubs/components/ClubsList';
import Page from '@components/Page';
import PageHeader from '@components/PageHeader';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohContainer from '@ui-kit/layout/Container';

const ClubsListPage = () => {
  const [searchParams] = useSearchParams();

  return (
    <Page title="Клубы">
      <Breadcrumb data={[{ href: '/clubs', text: 'Клубы', active: true }]} />
      <PohContainer>
        <PageHeader title="Клубы">&nbsp;</PageHeader>
        <ClubsList
          {...Object.fromEntries(searchParams)}
          listItemPatcher={(x) => ({
            as: Link,
            to: `/clubs/${x.id}`,
          })}
        />
      </PohContainer>
    </Page>
  );
};

export default ClubsListPage;
